# C: functions and recursion (50 problems). Uses cq() from build-problems-c-control.py.
IN = [("int", "n")]
LL = [("long long", "n")]
T = "Functions"
cq("c-fn-square", "Square with a Function", "EASY", T, "Write `long long square(int n)` that returns `n * n`. Read `n` and print the square.", "One integer.", "The square.", "|n| <= 10^6",
   '    printf("%lld\\n", square(n));', ["5", "-4", "0", "1000000", "12"], IN, defs="long long square(int n) {\n    return (long long)n * n;\n}")
cq("c-fn-cube", "Cube with a Function", "EASY", T, "Write `long long cube(int n)` that returns `n * n * n`. Read `n` and print it.", "One integer.", "The cube.", "|n| <= 10^5",
   '    printf("%lld\\n", cube(n));', ["3", "-3", "0", "100000", "10"], IN, defs="long long cube(int n) {\n    return (long long)n * n * n;\n}")
cq("c-fn-max2", "Maximum of Two", "EASY", T, "Write `int max2(int a, int b)` and print the larger of two integers with it.", "One line with two integers.", "The larger number.",
   '    printf("%d\\n", max2(a, b));', ["3 9", "9 3", "-4 -9", "5 5", "0 -1"], [("int", "a b")], defs="int max2(int a, int b) {\n    return a > b ? a : b;\n}")
cq("c-fn-max3", "Maximum of Three", "EASY", T, "Write `int max3(int a, int b, int c)` and print the largest of three integers.", "One line with three integers.", "The largest.",
   '    printf("%d\\n", max3(a, b, c));', ["1 2 3", "9 4 2", "5 10 7", "-1 -5 -3", "6 6 6"], [("int", "a b c")], defs="int max3(int a, int b, int c) {\n    int m = a;\n    if (b > m) m = b;\n    if (c > m) m = c;\n    return m;\n}")
cq("c-fn-min2", "Minimum of Two", "EASY", T, "Write `int min2(int a, int b)` and print the smaller of two integers with it.", "One line with two integers.", "The smaller number.",
   '    printf("%d\\n", min2(a, b));', ["3 9", "9 3", "-4 -9", "5 5", "0 -1"], [("int", "a b")], defs="int min2(int a, int b) {\n    return a < b ? a : b;\n}")
cq("c-fn-is-even", "Even or Odd Function", "EASY", T, "Write `int isEven(int n)` that returns 1 for even numbers and 0 for odd ones. Use it to print `Even` or `Odd`.", "One integer.", "`Even` or `Odd`.",
   '    printf("%s\\n", isEven(n) ? "Even" : "Odd");', ["4", "7", "0", "-3", "100"], IN, defs="int isEven(int n) {\n    return n % 2 == 0;\n}")
cq("c-fn-sign", "Sign Function", "EASY", T, "Write `const char *sign(int n)` that returns `Positive`, `Negative` or `Zero`. Print what it returns.", "One integer.", "One word.",
   '    printf("%s\\n", sign(n));', ["5", "-8", "0", "1", "-1"], IN, defs='const char *sign(int n) {\n    if (n > 0) return "Positive";\n    if (n < 0) return "Negative";\n    return "Zero";\n}')
cq("c-fn-leap-year", "Leap Year Function", "EASY", T, "Write `int isLeap(int year)`. Print `Leap year` or `Not a leap year`.", "One integer: the year.", "`Leap year` or `Not a leap year`.",
   '    printf("%s\\n", isLeap(n) ? "Leap year" : "Not a leap year");', ["2024", "1900", "2000", "2023", "2100"], IN, defs="int isLeap(int year) {\n    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;\n}")
cq("c-fn-is-prime", "Prime Function", "EASY", T, "Write `int isPrime(int n)` (returns 1 for a prime, else 0). Print `Prime` or `Not prime`.", "One positive integer.", "`Prime` or `Not prime`.", "1 <= n <= 10^9",
   '    printf("%s\\n", isPrime(n) ? "Prime" : "Not prime");', ["2", "1", "17", "100", "999999937"], IN, defs="int isPrime(int n) {\n    if (n < 2) return 0;\n    for (long long i = 2; i * i <= n; i++) if (n % i == 0) return 0;\n    return 1;\n}")
cq("c-fn-factorial", "Factorial Function", "EASY", T, "Write `long long factorial(int n)` and print `n!`.", "One integer.", "The factorial.", "0 <= n <= 20",
   '    printf("%lld\\n", factorial(n));', ["5", "0", "1", "10", "20"], IN, defs="long long factorial(int n) {\n    long long f = 1;\n    for (int i = 2; i <= n; i++) f *= i;\n    return f;\n}")
cq("c-fn-simple-interest", "Simple Interest", "EASY", T, "Write `double simpleInterest(double p, double r, double t)` returning `p * r * t / 100`. Read principal, rate and time and print the interest with two decimals.", "One line: `p r t` (decimals).", "The interest.",
   '    printf("%.2f\\n", simpleInterest(p, r, t));', ["1000 5 2", "5000 7.5 3", "0 10 1", "250.50 4 1.5", "100000 8 10"], [("double", "p r t")], defs="double simpleInterest(double p, double r, double t) {\n    return p * r * t / 100;\n}")
cq("c-fn-celsius-to-fahrenheit", "Celsius to Fahrenheit", "EASY", T, "Write `double toFahrenheit(double c)` using `c * 9 / 5 + 32`. Print the result with two decimals.", "One decimal: Celsius.", "Fahrenheit.",
   '    printf("%.2f\\n", toFahrenheit(c));', ["0", "100", "-40", "36.6", "25"], [("double", "c")], defs="double toFahrenheit(double c) {\n    return c * 9 / 5 + 32;\n}")
cq("c-fn-fahrenheit-to-celsius", "Fahrenheit to Celsius", "EASY", T, "Write `double toCelsius(double f)` using `(f - 32) * 5 / 9`. Print the result with two decimals.", "One decimal: Fahrenheit.", "Celsius.",
   '    printf("%.2f\\n", toCelsius(f));', ["32", "212", "-40", "98.6", "77"], [("double", "f")], defs="double toCelsius(double f) {\n    return (f - 32) * 5 / 9;\n}")
cq("c-fn-circle", "Circle Area and Circumference", "MEDIUM", T, "Write `double circle(double r, double *circumference)` that returns the area and stores the circumference through the pointer. Use pi = 3.14159. Print `Area: <a>` and `Circumference: <c>` with two decimals.", "One decimal: radius.", "Two lines.",
   '    double c;\n    double a = circle(r, &c);\n    printf("Area: %.2f\\nCircumference: %.2f\\n", a, c);', ["1", "2.5", "10", "0", "7.25"], [("double", "r")], defs="double circle(double r, double *circumference) {\n    *circumference = 2 * 3.14159 * r;\n    return 3.14159 * r * r;\n}")
cq("c-fn-heron", "Triangle Area by Heron's Formula", "MEDIUM", T, "Write `double heron(double a, double b, double c)` using `s = (a+b+c)/2` and `sqrt(s(s-a)(s-b)(s-c))`. If the sides cannot form a triangle print `Invalid triangle`, otherwise print the area with two decimals.", "One line with three decimals.", "The area or a message.",
   '    if (a + b <= c || a + c <= b || b + c <= a) printf("Invalid triangle\\n");\n    else printf("%.2f\\n", heron(a, b, c));', ["3 4 5", "5 5 5", "1 2 3", "7 10 5", "6 8 10"], [("double", "a b c")], inc="#include <math.h>\n", defs="double heron(double a, double b, double c) {\n    double s = (a + b + c) / 2;\n    return sqrt(s * (s - a) * (s - b) * (s - c));\n}")
cq("c-fn-swap", "Swap with a Function", "EASY", T, "Write `void swap(int *x, int *y)`. Read two integers, swap them with it and print `a b`.", "One line with two integers.", "The swapped values.",
   '    swap(&a, &b);\n    printf("%d %d\\n", a, b);', ["3 5", "-7 2", "0 0", "100 -100", "15 30"], [("int", "a b")], defs="void swap(int *x, int *y) {\n    int t = *x;\n    *x = *y;\n    *y = t;\n}")
cq("c-fn-is-vowel", "Vowel Function", "EASY", T, "Write `int isVowel(char c)` (either case). Print `Vowel` or `Consonant` for a letter.", "One letter.", "`Vowel` or `Consonant`.",
   '    printf("%s\\n", isVowel(c) ? "Vowel" : "Consonant");', ["a", "B", "E", "z", "u"], [("char", "c")], defs="int isVowel(char c) {\n    if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';\n    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';\n}")
cq("c-fn-letter-case", "Letter Case Function", "EASY", T, "Write `const char *letterCase(char c)` returning `Uppercase`, `Lowercase` or `Not a letter`. Print the result.", "One character.", "One result.",
   '    printf("%s\\n", letterCase(c));', ["A", "z", "5", "#", "m"], [("char", "c")], defs='const char *letterCase(char c) {\n    if (c >= \'A\' && c <= \'Z\') return "Uppercase";\n    if (c >= \'a\' && c <= \'z\') return "Lowercase";\n    return "Not a letter";\n}')
cq("c-fn-count-digits", "Count Digits Function", "EASY", T, "Write `int countDigits(int n)` (a `0` has one digit). Print the result.", "One non-negative integer.", "The count.",
   '    printf("%d\\n", countDigits(n));', ["12345", "0", "7", "1000000000", "90"], IN, defs="int countDigits(int n) {\n    int count = 0;\n    do {\n        count++;\n        n /= 10;\n    } while (n > 0);\n    return count;\n}")
cq("c-fn-sum-digits", "Sum of Digits Function", "EASY", T, "Write `int sumDigits(int n)` and print the sum of the digits.", "One non-negative integer.", "The sum.",
   '    printf("%d\\n", sumDigits(n));', ["1234", "0", "9", "999999999", "1001"], IN, defs="int sumDigits(int n) {\n    int sum = 0;\n    while (n > 0) {\n        sum += n % 10;\n        n /= 10;\n    }\n    return sum;\n}")
cq("c-fn-reverse-number", "Reverse Function", "EASY", T, "Write `long long reverse(int n)` and print the digits of `n` reversed as a number.", "One non-negative integer.", "The reversed number.",
   '    printf("%lld\\n", reverse(n));', ["1234", "1200", "0", "7", "987654321"], IN, defs="long long reverse(int n) {\n    long long rev = 0;\n    while (n > 0) {\n        rev = rev * 10 + n % 10;\n        n /= 10;\n    }\n    return rev;\n}")
cq("c-fn-palindrome", "Palindrome Function", "EASY", T, "Write `int isPalindrome(int n)` and print `Yes` or `No`.", "One non-negative integer.", "`Yes` or `No`.",
   '    printf("%s\\n", isPalindrome(n) ? "Yes" : "No");', ["121", "123", "7", "1221", "10"], IN, defs="int isPalindrome(int n) {\n    int original = n;\n    long long rev = 0;\n    while (n > 0) {\n        rev = rev * 10 + n % 10;\n        n /= 10;\n    }\n    return rev == original;\n}")
cq("c-fn-armstrong", "Armstrong Function", "MEDIUM", T, "Write `int isArmstrong(int n)`: the digits, each raised to the number of digits, add up to `n`. Print `Yes` or `No`.", "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^7",
   '    printf("%s\\n", isArmstrong(n) ? "Yes" : "No");', ["153", "1634", "9474", "123", "9"], IN, defs="int isArmstrong(int n) {\n    int digits = 0;\n    for (int t = n; t > 0; t /= 10) digits++;\n    long long sum = 0;\n    for (int t = n; t > 0; t /= 10) {\n        long long p = 1;\n        for (int i = 0; i < digits; i++) p *= t % 10;\n        sum += p;\n    }\n    return sum == n;\n}")
cq("c-fn-gcd", "GCD Function", "EASY", T, "Write `int gcd(int a, int b)` and print the greatest common divisor.", "One line: `a b`.", "The GCD.", "1 <= a, b <= 10^9",
   '    printf("%d\\n", gcd(a, b));', ["12 18", "17 5", "100 75", "1 1", "1000000000 250000000"], [("int", "a b")], defs="int gcd(int a, int b) {\n    while (b != 0) {\n        int t = a % b;\n        a = b;\n        b = t;\n    }\n    return a;\n}")
cq("c-fn-lcm", "LCM Function", "EASY", T, "Write `long long lcm(int a, int b)` and print the least common multiple.", "One line: `a b`.", "The LCM.", "1 <= a, b <= 10^6",
   '    printf("%lld\\n", lcm(a, b));', ["4 6", "7 5", "12 18", "1 1", "1000000 999999"], [("int", "a b")], defs="int gcd(int a, int b) {\n    while (b != 0) {\n        int t = a % b;\n        a = b;\n        b = t;\n    }\n    return a;\n}\n\nlong long lcm(int a, int b) {\n    return (long long)a / gcd(a, b) * b;\n}")

T = "Recursion"
cq("c-rec-factorial", "Recursive Factorial", "EASY", T, "Write a recursive `long long fact(int n)` and print `n!`.", "One integer.", "The factorial.", "0 <= n <= 20",
   '    printf("%lld\\n", fact(n));', ["5", "0", "1", "10", "20"], IN, defs="long long fact(int n) {\n    return n <= 1 ? 1 : n * fact(n - 1);\n}")
cq("c-rec-fibonacci", "Recursive Fibonacci", "EASY", T, "Write a recursive `int fib(int n)` with `fib(0) = 0`, `fib(1) = 1`. Print `fib(n)`.", "One integer.", "The number.", "0 <= n <= 30",
   '    printf("%d\\n", fib(n));', ["10", "0", "1", "20", "30"], IN, defs="int fib(int n) {\n    return n < 2 ? n : fib(n - 1) + fib(n - 2);\n}")
cq("c-rec-sum-natural", "Recursive Sum of 1..N", "EASY", T, "Write a recursive `long long sum(int n)` returning `1 + 2 + ... + n`.", "One integer.", "The sum.", "0 <= n <= 10000",
   '    printf("%lld\\n", sum(n));', ["10", "0", "1", "100", "10000"], IN, defs="long long sum(int n) {\n    return n == 0 ? 0 : n + sum(n - 1);\n}")
cq("c-rec-power", "Recursive Power", "EASY", T, "Write a recursive `long long power(int a, int b)` returning `a` raised to `b`.", "One line: `a b`.", "The result.", "1 <= a <= 10, 0 <= b <= 15",
   '    printf("%lld\\n", power(a, b));', ["2 10", "5 0", "10 15", "3 4", "1 9"], [("int", "a b")], defs="long long power(int a, int b) {\n    return b == 0 ? 1 : a * power(a, b - 1);\n}")
cq("c-rec-gcd", "Recursive GCD", "EASY", T, "Write a recursive `int gcd(int a, int b)` and print the GCD.", "One line: `a b`.", "The GCD.", "1 <= a, b <= 10^9",
   '    printf("%d\\n", gcd(a, b));', ["12 18", "17 5", "100 75", "1 1", "1000000000 250000000"], [("int", "a b")], defs="int gcd(int a, int b) {\n    return b == 0 ? a : gcd(b, a % b);\n}")
cq("c-rec-print-up", "Print 1 to N Recursively", "EASY", T, "Write a recursive `void up(int i, int n)` that prints `1 2 ... n` on one line (numbers separated by spaces).", "One integer.", "The numbers.", "1 <= n <= 1000",
   '    up(1, n);\n    printf("\\n");', ["5", "1", "10", "20", "3"], IN, defs='void up(int i, int n) {\n    if (i > n) return;\n    printf("%d%s", i, i < n ? " " : "");\n    up(i + 1, n);\n}')
cq("c-rec-print-down", "Print N to 1 Recursively", "EASY", T, "Write a recursive `void down(int n)` that prints `n n-1 ... 1` on one line.", "One integer.", "The numbers.", "1 <= n <= 1000",
   '    down(n);\n    printf("\\n");', ["5", "1", "10", "20", "3"], IN, defs='void down(int n) {\n    if (n == 0) return;\n    printf("%d%s", n, n > 1 ? " " : "");\n    down(n - 1);\n}')
cq("c-rec-count-digits", "Recursive Digit Count", "EASY", T, "Write a recursive `int digits(int n)` and print how many digits `n` has (`0` has one).", "One non-negative integer.", "The count.",
   '    printf("%d\\n", digits(n));', ["12345", "0", "7", "1000000000", "90"], IN, defs="int digits(int n) {\n    return n < 10 ? 1 : 1 + digits(n / 10);\n}")
cq("c-rec-sum-digits", "Recursive Sum of Digits", "EASY", T, "Write a recursive `int sumDigits(int n)`.", "One non-negative integer.", "The sum.",
   '    printf("%d\\n", sumDigits(n));', ["1234", "0", "9", "999999999", "1001"], IN, defs="int sumDigits(int n) {\n    return n == 0 ? 0 : n % 10 + sumDigits(n / 10);\n}")
cq("c-rec-reverse-number", "Recursive Reverse", "MEDIUM", T, "Write a recursive `long long rev(long long n, long long acc)` that reverses the digits (call it with `acc = 0`). Print the reversed number.", "One non-negative integer.", "The reversed number.", "0 <= n <= 10^9",
   '    printf("%lld\\n", rev(n, 0));', ["1234", "1200", "0", "7", "987654321"], LL, defs="long long rev(long long n, long long acc) {\n    return n == 0 ? acc : rev(n / 10, acc * 10 + n % 10);\n}")
cq("c-rec-palindrome-number", "Recursive Palindrome Number", "MEDIUM", T, "Use a recursive reverse to decide if a number is a palindrome. Print `Yes` or `No`.", "One non-negative integer.", "`Yes` or `No`.",
   '    printf("%s\\n", rev(n, 0) == n ? "Yes" : "No");', ["121", "123", "7", "1221", "10"], LL, defs="long long rev(long long n, long long acc) {\n    return n == 0 ? acc : rev(n / 10, acc * 10 + n % 10);\n}")
cq("c-rec-binary", "Recursive Decimal to Binary", "MEDIUM", T, "Write a recursive `void toBinary(int n)` that prints the binary digits of `n` (print `0` for 0).", "One non-negative integer.", "The binary digits.", "0 <= n <= 10^9",
   '    if (n == 0) printf("0");\n    else toBinary(n);\n    printf("\\n");', ["10", "0", "1", "255", "1000000000"], IN, defs='void toBinary(int n) {\n    if (n == 0) return;\n    toBinary(n / 2);\n    printf("%d", n % 2);\n}')
cq("c-rec-array-sum", "Recursive Array Sum", "EASY", T, "Write a recursive `long long sum(int a[], int n)` returning the sum of the first `n` elements.", "First line `n`, then `n` integers.", "The sum.", "1 <= n <= 1000",
   '    printf("%lld\\n", sum(a, n));', [arr([1, 2, 3, 4]), arr([10]), arr([-5, 5, 10]), arr([100, 200, 300, 401]), arr([7, 7, 7])], [("arr", "n a")], defs="long long sum(int a[], int n) {\n    return n == 0 ? 0 : a[n - 1] + sum(a, n - 1);\n}")
cq("c-rec-array-max", "Recursive Array Maximum", "EASY", T, "Write a recursive `int maxOf(int a[], int n)` returning the largest of the first `n` elements.", "First line `n`, then `n` integers.", "The maximum.", "1 <= n <= 1000",
   '    printf("%d\\n", maxOf(a, n));', [arr([1, 9, 3]), arr([10]), arr([-5, -9, -1]), arr([100, 200, 50, 401]), arr([7, 7, 7])], [("arr", "n a")], defs="int maxOf(int a[], int n) {\n    if (n == 1) return a[0];\n    int rest = maxOf(a, n - 1);\n    return a[n - 1] > rest ? a[n - 1] : rest;\n}")
cq("c-rec-string-palindrome", "Recursive String Palindrome", "MEDIUM", T, "Write a recursive `int isPal(const char *s, int i, int j)`. Print `Yes` if the word reads the same backwards, else `No`.", "One word (up to 100 characters).", "`Yes` or `No`.",
   '    int len = 0;\n    while (s[len]) len++;\n    printf("%s\\n", isPal(s, 0, len - 1) ? "Yes" : "No");', ["level", "hello", "a", "abba", "noon1"], [("str", "s")], defs="int isPal(const char *s, int i, int j) {\n    if (i >= j) return 1;\n    return s[i] == s[j] && isPal(s, i + 1, j - 1);\n}")
cq("c-rec-string-length", "Recursive String Length", "EASY", T, "Write a recursive `int len(const char *s)` and print the length of the word.", "One word (up to 100 characters).", "The length.",
   '    printf("%d\\n", len(s));', ["hello", "a", "programming", "NextByte", "abcdefghijklmnopqrstuvwxyz"], [("str", "s")], defs="int len(const char *s) {\n    return *s == '\\0' ? 0 : 1 + len(s + 1);\n}")
cq("c-rec-string-copy", "Recursive String Copy", "MEDIUM", T, "Write a recursive `void copy(char *dst, const char *src)` that copies a string including the end marker. Copy the word and print the copy.", "One word (up to 100 characters).", "The copy.",
   '    char t[101];\n    copy(t, s);\n    printf("%s\\n", t);', ["hello", "a", "programming", "NextByte", "12345"], [("str", "s")], defs="void copy(char *dst, const char *src) {\n    *dst = *src;\n    if (*src) copy(dst + 1, src + 1);\n}")
cq("c-rec-hanoi", "Towers of Hanoi", "MEDIUM", T, "Move `n` disks from peg A to peg C using peg B. Write a recursive function and print every move as `Move disk <d> from <x> to <y>`, then a last line `Total moves: <count>`.", "One integer `n`.", "The moves, then the total.", "1 <= n <= 6",
   '    int count = 0;\n    hanoi(n, \'A\', \'C\', \'B\', &count);\n    printf("Total moves: %d\\n", count);', ["1", "2", "3", "4", "6"], IN, defs='void hanoi(int n, char from, char to, char via, int *count) {\n    if (n == 0) return;\n    hanoi(n - 1, from, via, to, count);\n    printf("Move disk %d from %c to %c\\n", n, from, to);\n    (*count)++;\n    hanoi(n - 1, via, to, from, count);\n}')
cq("c-rec-ap-term", "N-th Term of an AP", "EASY", T, "Write a recursive `long long ap(long long a, long long d, int n)` giving the n-th term of an arithmetic progression with first term `a` and difference `d` (the first term is n = 1).", "One line: `a d n`.", "The n-th term.", "1 <= n <= 1000",
   '    printf("%lld\\n", ap(a, d, n));', ["3 4 5", "10 -2 4", "0 5 1", "7 0 100", "1 1 1000"], [("long long", "a d"), ("int", "n")], defs="long long ap(long long a, long long d, int n) {\n    return n == 1 ? a : d + ap(a, d, n - 1);\n}")
cq("c-rec-gp-term", "N-th Term of a GP", "EASY", T, "Write a recursive `long long gp(long long a, long long r, int n)` giving the n-th term of a geometric progression (first term `a`, ratio `r`, first term is n = 1).", "One line: `a r n`.", "The n-th term.", "1 <= n <= 30, |a|, |r| <= 5",
   '    printf("%lld\\n", gp(a, r, n));', ["3 2 5", "1 3 10", "5 1 20", "2 -2 6", "4 5 12"], [("long long", "a r"), ("int", "n")], defs="long long gp(long long a, long long r, int n) {\n    return n == 1 ? a : r * gp(a, r, n - 1);\n}")
cq("c-rec-multiply", "Multiply Using Addition", "EASY", T, "Write a recursive `long long mul(int a, int b)` that multiplies using only addition (`b` is not negative).", "One line: `a b`.", "The product.", "|a| <= 1000, 0 <= b <= 1000",
   '    printf("%lld\\n", mul(a, b));', ["6 7", "-3 5", "0 9", "12 0", "1000 1000"], [("int", "a b")], defs="long long mul(int a, int b) {\n    return b == 0 ? 0 : a + mul(a, b - 1);\n}")
cq("c-rec-is-prime", "Recursive Prime Check", "MEDIUM", T, "Write a recursive `int check(int n, int d)` that tests divisors from `d` upward. Print `Prime` or `Not prime`.", "One positive integer.", "`Prime` or `Not prime`.", "1 <= n <= 5000",
   '    printf("%s\\n", n >= 2 && check(n, 2) ? "Prime" : "Not prime");', ["2", "1", "17", "100", "4999"], IN, defs="int check(int n, int d) {\n    if (d * d > n) return 1;\n    if (n % d == 0) return 0;\n    return check(n, d + 1);\n}")
cq("c-rec-print-array-reverse", "Print an Array Backwards", "EASY", T, "Write a recursive `void rev(int a[], int n)` that prints the elements from last to first on one line.", "First line `n`, then `n` integers.", "The elements in reverse.", "1 <= n <= 1000",
   '    rev(a, n);\n    printf("\\n");', [arr([1, 2, 3, 4, 5]), arr([7]), arr([10, -3, 8, 8]), arr([5, 4, 3, 2, 1, 0]), arr([-1, -2, -3])], [("arr", "n a")], defs='void rev(int a[], int n) {\n    if (n == 0) return;\n    printf("%d%s", a[n - 1], n > 1 ? " " : "");\n    rev(a, n - 1);\n}')
cq("c-rec-count-digit", "Count a Digit Recursively", "EASY", T, "Write a recursive `int countDigit(long long n, int d)` that counts how many times digit `d` appears in `n`.", "One line: `n d`.", "The count.", "0 <= n <= 10^12, 0 <= d <= 9",
   '    printf("%d\\n", countDigit(n, d));', ["1232123 2", "1000 0", "0 0", "999 9", "12345 7"], [("long long", "n"), ("int", "d")], defs="int countDigit(long long n, int d) {\n    if (n == 0) return 0;\n    return (n % 10 == d) + countDigit(n / 10, d);\n}")
cq("c-rec-digital-root", "Digital Root", "MEDIUM", T, "The digital root is found by adding the digits again and again until one digit is left (`9875` gives `29`, then `11`, then `2`). Write it recursively.", "One non-negative integer.", "The digital root.", "0 <= n <= 10^9",
   '    printf("%d\\n", root(n));', ["9875", "0", "7", "999999999", "1234"], IN, defs="int root(int n) {\n    if (n < 10) return n;\n    int sum = 0;\n    while (n > 0) {\n        sum += n % 10;\n        n /= 10;\n    }\n    return root(sum);\n}")
